*/
typedef struct
{
   char     name[ 16 ];
   VM_OWNER vm_mem;
   DWORD    size;
   DWORD    offset;
   DWORD    flags;
	DWORD		lock_cnt;
} ITEMINFO;

typedef struct
{
   char     filepath[ _MAX_PATH ];
   ITEMINFO *item;
   int      items;
   int      handle;
   int      permissions;
} FILEDESC;

typedef struct
{
