PRIVATE CHAR *    serial = "32768GLB";
PRIVATE CHAR      exePath[ _MAX_PATH ];
PRIVATE INT       num_glbs;
PRIVATE KEYFILE   g_key;
PRIVATE CHAR      prefix[5] = "FILE";
