/*
* define file descriptor used to access file.
*/
typedef struct
{
   char     name[ 16 ];
   VM_OWNER vm_mem;
   DWORD    size;
   DWORD    offset;
   DWORD    flags;
	DWORD		lock_cnt;
} ITEMINFO;

typedef struct
{
   char     filepath[ _MAX_PATH ];
   ITEMINFO *item;
   int      items;
   int      handle;
   int      permissions;
} FILEDESC;

typedef struct
{
   WORD     itemnum;
   WORD     filenum;
} ITEM_ID;

typedef union
{
   ITEM_ID  id;
   DWORD    handle;
} ITEM_H;

PRIVATE FILEDESC  filedesc[ MAX_GLB_FILES ];

#define ITF_LOCKED  0x80000000L
#define ITF_ENCODED 0x40000000L

/***************************************************************************
  GLB_EnCrypt - Encrypt Data
 ***************************************************************************/
VOID
GLB_EnCrypt(
CHAR     *key,             // INPUT : Key that will allow Decryption
BYTE     *buffer,          // INPUT : Buffer to Encrypt
size_t   length            // INPUT : Length of Buffer
)
{
   INT   klen = strlen( key );
   INT   prev_byte;
   INT   kidx;

   kidx = SEED % klen;
   prev_byte = key[ kidx ];
   while ( length-- )
   {
      prev_byte = ( *buffer + key[ kidx ] + prev_byte ) % 256;
      *buffer++ = prev_byte;

      if ( ++kidx >= klen )
         kidx = 0;
   }
}

/***************************************************************************
  GLB_DeCrypt - Decrypt Data
 ***************************************************************************/
VOID
GLB_DeCrypt(
CHAR    *key,               // INPUT : Key that will allow Decryption
BYTE    *buffer,            // INPUT : Buffer to Encrypt
size_t  length              // INPUT : Length of Buffer
)
{
   INT   klen = strlen( key );
   INT   prev_byte;
   INT   kidx;
   CHAR  dchr;

   kidx = SEED % klen;
   prev_byte = key[ kidx ];
   while ( length-- )
   {
      dchr = ( *buffer - key[ kidx ] - prev_byte ) % 256;
      prev_byte = *buffer;
      *buffer++ = dchr;

      if ( ++kidx >= klen )
         kidx = 0;
   }
}

