      rval = 2;
      if ( image ) *image += -*x;
      *lx += *x;
      *x = 0;
   }

   if ( *x + *lx > SCREENWIDTH )
   {
      rval = 2;
      *lx = SCREENWIDTH - *x;
   }

   return ( rval );
}

